Running command: cd /workspace && cat > test_fuzz.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "blosc.h"
int main() {
  int size = 200000;
  unsigned char *data = malloc(size);
  unsigned char *output = malloc(size + 1);
  srand(1);
  for (int i = 0; i < size; i++) data[i] = rand() & 0xff;
  // header bytes
  data[0] = 9; data[1] = 0; data[2] = 0; data[3] = 0; data[4] = 0;
  // probe region: last 4096 bytes zeros
  memset(data + size - 4096, 0, 4096);
  int r = blosc_compress(9, 0, 1, size, data, output, size);
  printf("result=%d\n", r);
  return 0;
}
EOF
gcc -fsanitize=address -g -O1 -I./repo-vul/src-vul/c-blosc/blosc test_fuzz.c ./repo-vul/src-vul/c-blosc/build/blosc/libblosc.a -o test_fuzz -lpthread 2>&1 | tail -5
export ASAN_OPTIONS=detect_leaks=0
./test_fuzz 2>&1 | tail -30

